import { mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { gunzipSync } from "node:zlib";
const payload = "[... ELLIPSIZATION ...]";
const files = JSON.parse(gunzipSync(Buffer.from(payload, "base64")).toString("utf8"));
for (const [file, encoded] of Object.entries(files)) { mkdirSync(dirname(file), { recursive: true }); writeFileSync(file, Buffer.from(encoded, "base64")); }
console.log(`V020_SOURCE_BUNDLE_WRITTEN files=${Object.keys(files).length}`);
await import("./apply-v020-evolution-tracks.mjs");
